using System;
using System.IO;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace CrossServiceAuth
{
    /// <summary>
    /// Native interop layer for high-performance token validation
    /// Uses platform-native crypto for HMAC verification before deserialization
    /// </summary>
    public static class NativeTokenValidator
    {
        [DllImport("libtoken_verify", CallingConvention = CallingConvention.Cdecl)]
        private static extern int native_hmac_verify(
            byte[] key, int keyLen,
            byte[] data, int dataLen,
            byte[] signature, int sigLen);

        [DllImport("libtoken_verify", CallingConvention = CallingConvention.Cdecl)]
        private static extern int native_get_payload_length(byte[] envelope, int envelopeLen);
    }

    public class AuthTokenEnvelope
    {
        public string ServiceId { get; set; }
        public long Timestamp { get; set; }
        public string PayloadType { get; set; }
        public byte[] Payload { get; set; }
        public byte[] Signature { get; set; }
    }

    public class ServiceCredential
    {
        public string ServiceName { get; set; }
        public string[] Permissions { get; set; }
        public DateTime ValidUntil { get; set; }
    }

    public interface IPayloadDeserializer
    {
        object Deserialize(byte[] data, string typeName);
    }

    public class SecurePayloadDeserializer : IPayloadDeserializer
    {
        private static readonly HashSet<string> _allowedTypes = new HashSet<string>
        {
            "CrossServiceAuth.ServiceCredential",
            "CrossServiceAuth.AuthTokenEnvelope"
        };

        public object Deserialize(byte[] data, string typeName)
        {
            if (!_allowedTypes.Contains(typeName))
                throw new InvalidOperationException($"Type {typeName} not in allowlist");

            return JsonSerializer.Deserialize(data, Type.GetType(typeName));
        }
    }

    public class TokenValidationService
    {
        private readonly byte[] _sharedSecret;
        private readonly IPayloadDeserializer _deserializer;
        private readonly int _maxClockSkewSeconds;

        public TokenValidationService(byte[] sharedSecret, IPayloadDeserializer deserializer, int maxClockSkewSeconds = 300)
        {
            _sharedSecret = sharedSecret ?? throw new ArgumentNullException(nameof(sharedSecret));
            _deserializer = deserializer ?? throw new ArgumentNullException(nameof(deserializer));
            _maxClockSkewSeconds = maxClockSkewSeconds;
        }

        public (bool IsValid, ServiceCredential Credential) ValidateToken(byte[] rawEnvelope)
        {
            if (rawEnvelope == null || rawEnvelope.Length == 0)
                return (false, null);

            AuthTokenEnvelope envelope;
            try
            {
                envelope = JsonSerializer.Deserialize<AuthTokenEnvelope>(rawEnvelope);
            }
            catch
            {
                return (false, null);
            }

            if (envelope?.Payload == null || envelope.Signature == null)
                return (false, null);

            // Verify timestamp freshness
            var tokenTime = DateTimeOffset.FromUnixTimeSeconds(envelope.Timestamp);
            var skew = Math.Abs((DateTimeOffset.UtcNow - tokenTime).TotalSeconds);
            if (skew > _maxClockSkewSeconds)
                return (false, null);

            // Verify HMAC signature over payload
            if (!VerifySignature(envelope))
                return (false, null);

            // Deserialize the authenticated payload
            try
            {
                var credential = _deserializer.Deserialize(envelope.Payload, envelope.PayloadType)
                    as ServiceCredential;
                if (credential == null)
                    return (false, null);

                if (credential.ValidUntil < DateTime.UtcNow)
                    return (false, null);

                return (true, credential);
            }
            catch
            {
                return (false, null);
            }
        }

        private bool VerifySignature(AuthTokenEnvelope envelope)
        {
            // Compute HMAC over: ServiceId || Timestamp || Payload
            var dataToSign = BuildSigningInput(envelope);

            // Use managed fallback if native library unavailable
            using var hmac = new HMACSHA256(_sharedSecret);
            var computed = hmac.ComputeHash(dataToSign);

            return TimingSafeCompare(computed, envelope.Signature);
        }

        private byte[] BuildSigningInput(AuthTokenEnvelope envelope)
        {
            using var ms = new MemoryStream();
            var serviceBytes = Encoding.UTF8.GetBytes(envelope.ServiceId ?? "");
            var timestampBytes = BitConverter.GetBytes(envelope.Timestamp);

            ms.Write(serviceBytes, 0, serviceBytes.Length);
            ms.Write(timestampBytes, 0, timestampBytes.Length);
            ms.Write(envelope.Payload, 0, envelope.Payload.Length);
            return ms.ToArray();
        }

        /// <summary>
        /// Constant-time comparison to prevent timing attacks
        /// </summary>
        private static bool TimingSafeCompare(byte[] a, byte[] b)
        {
            if (a.Length != b.Length)
                return false;

            uint diff = 0;
            for (int i = 0; i < a.Length; i++)
            {
                diff |= (uint)(a[i] ^ b[i]);
            }
            return diff == 0;
        }
    }

    /// <summary>
    /// Cross-service authentication middleware
    /// </summary>
    public class AuthMiddleware
    {
        private readonly TokenValidationService _validator;
        private readonly Dictionary<string, string[]> _servicePermissions;

        public AuthMiddleware(TokenValidationService validator)
        {
            _validator = validator;
            _servicePermissions = new Dictionary<string, string[]>();
        }

        public bool AuthorizeRequest(byte[] tokenBytes, string requiredPermission)
        {
            var (isValid, credential) = _validator.ValidateToken(tokenBytes);
            if (!isValid || credential == null)
                return false;

            return credential.Permissions?.Contains(requiredPermission) ?? false;
        }
    }

    /// <summary>
    /// Token generation for service-to-service calls
    /// </summary>
    public class TokenGenerator
    {
        private readonly byte[] _sharedSecret;

        public TokenGenerator(byte[] sharedSecret)
        {
            _sharedSecret = sharedSecret;
        }

        public byte[] GenerateToken(string serviceId, ServiceCredential credential)
        {
            var payload = JsonSerializer.SerializeToUtf8Bytes(credential);
            var envelope = new AuthTokenEnvelope
            {
                ServiceId = serviceId,
                Timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds(),
                PayloadType = typeof(ServiceCredential).FullName,
                Payload = payload
            };

            // Sign: ServiceId || Timestamp || Payload
            using var ms = new MemoryStream();
            var serviceBytes = Encoding.UTF8.GetBytes(envelope.ServiceId);
            var timestampBytes = BitConverter.GetBytes(envelope.Timestamp);
            ms.Write(serviceBytes, 0, serviceBytes.Length);
            ms.Write(timestampBytes, 0, timestampBytes.Length);
            ms.Write(payload, 0, payload.Length);

            using var hmac = new HMACSHA256(_sharedSecret);
            envelope.Signature = hmac.ComputeHash(ms.ToArray());

            return JsonSerializer.SerializeToUtf8Bytes(envelope);
        }
    }
}
